var WORKFLOW_PATH_PREFIX = '.github/workflows/';

function isValidationWorkflowPath(p, ciWorkflow) {
    if (!p || !ciWorkflow) return false;
    if (p === WORKFLOW_PATH_PREFIX + ciWorkflow) return true;
