      id: 37923501714, name: 'review (SM)', event: 'workflow_dispatch',
      path: '.github/workflows/ai-teammate.yml',
      created_at: '2026-10-09T11:20:00Z', updated_at: '2026-10-09T11:24:00Z',
      html_url: 'http://run/review'
