    // gh-816) alongside the gh-769 clock split.
    function runCite(r) {
        var t = runClock(r);
        var done = r.status === 'completed';
        return {
            verdict: done ? (r.conclusion || r.status) : r.status,
            at: r.created_at,
            url: r.html_url,
            runId: r.id == null ? null : r.id,
            name: r.name || null,
