    // gh-816 thread 2: among real runs, the machine's own validation
    // workflow (path match) outranks every other real run (score 2 vs 1) —
    // an unrelated repo workflow (labeler/docs/lint arriving on a
    // non-dispatch event) is still fail-open real, but it may only cite
    // when nothing better exists. Ties break on freshness; within a tier a
    // terminal non-cancelled verdict outranks an in-flight run (gh-191).
    function runScore(r) {
        return isValidationWorkflowPath(r.path, ciWorkflow) ? 2 : 1;
    }
    function freshestFirst(a, b) {
        return String((b && (b.updated_at || b.created_at)) || '')
            .localeCompare(String((a && (a.updated_at || a.created_at)) || ''));
    }
    function bestRun(pool) {
        var list = (pool || []).slice().sort(function (a, b) {
            return (runScore(b) - runScore(a)) || freshestFirst(a, b);
        });
        return list[0] || null;
    }
    function headVerdict(sha) {
