        return out;
    }","path":"/home/runner/work/dmtools-agents/dmtools-agents/js/factoryState.js"}

{"newText":"        // gh-816: PERSIST the checks record at merge time — resolve the
        // head's real validation cite from the current runs list (the list
        // is repo-wide, the merged head still matches), else carry the
